"""Phase 5 TMP collapse 与 materialization 的公开 demo 程序片段。

Collapse 只由显式 temporary evidence 驱动：``CREATE TEMP`` /
``CREATE TEMPORARY TABLE``。``TMP_`` / ``TEMP_`` / ``STG_`` / ``TEST_`` 名称本身
没有任何资产语义，因此 fixture 必须显式声明 temporary 意图。
"""

SINGLE_TMP_PROGRAM = """
execute("CREATE TEMPORARY TABLE TMP_1 AS SELECT * FROM ODS.DEMO_A")
execute("INSERT INTO DWA.DEMO_RESULT SELECT * FROM TMP_1")
"""

MULTI_HOP_TMP_PROGRAM = """
execute("CREATE TEMPORARY TABLE TMP_1 AS SELECT * FROM ODS.DEMO_A")
execute("CREATE TEMPORARY TABLE TMP_2 AS SELECT * FROM TMP_1")
execute("CREATE TEMPORARY TABLE TMP_3 AS SELECT * FROM TMP_2")
execute("INSERT INTO DWA.DEMO_RESULT SELECT * FROM TMP_3")
"""

MULTI_SOURCE_PROGRAM = """
execute("CREATE TEMPORARY TABLE TMP_1 AS SELECT * FROM ODS.DEMO_A JOIN DWF.DEMO_B ON 1 = 1")
execute("CREATE TEMPORARY TABLE TMP_2 AS SELECT * FROM TMP_1 JOIN DWM.DEMO_STAGE ON 1 = 1")
execute("INSERT INTO DWA.DEMO_RESULT SELECT * FROM TMP_2 JOIN DWA.DEMO_DIM ON 1 = 1")
"""

FORMAL_BOUNDARY_PROGRAM = """
execute("INSERT INTO DWM.DEMO_STAGE SELECT * FROM ODS.DEMO_A")
execute("CREATE TEMPORARY TABLE TMP_1 AS SELECT * FROM DWM.DEMO_STAGE")
execute("INSERT INTO DWA.DEMO_RESULT SELECT * FROM TMP_1")
"""

